def f(N: int, M: int, C: int, connections: List[Tuple[int, int, int]]) -> int:
    import heapq
    graph = [[] for _ in range(N)]
    for a, b, d in connections:
        graph[a-1].append((-d, b-1))
        graph[b-1].append((d, a-1))
    pq = [(0, -1, 0)]
    visited = [0] * (N)
    max_weight = 0
    while pq:
        weight, node, total = heapq.heappop(pq)
        weight *= -1
        if visited[node]:
            if total > max_weight:
                max_weight = total
            continue
        visited[node] = 1
        for delta, adj_node in graph[node]:
            if visited[adj_node]:
                heapq.heappush(pq, (weight - delta, adj_node, total - abs(delta)))
            else:
                heapq.heappush(pq, (weight + delta, adj_node, total + abs(delta)))
    if max_weight < C:
        return 0
    else:
        return max_weight - C
```

